#include <QApplication>
#include <QAbstractScrollArea>
#include <QElapsedTimer>
#include <QEventLoop>
#include <QJsonArray>
#include <QJsonDocument>
#include <QJsonObject>
#include <QTimer>
#include <QWidget>

#include <algorithm>
#include <memory>
#include <vector>

namespace {
void drainEvents(int milliseconds)
{
    QEventLoop loop;
    QTimer::singleShot(milliseconds, &loop, &QEventLoop::quit);
    loop.exec();
}

qint64 maxGap(const std::vector<qint64>& ticks)
{
    qint64 result = 0;
    for (size_t i = 1; i < ticks.size(); ++i)
        result = std::max(result, ticks[i] - ticks[i - 1]);
    return result;
}
} // namespace

int main(int argc, char** argv)
{
    bool useScrollArea = false;
    for (int i = 1; i < argc; ++i) {
        if (QString::fromLocal8Bit(argv[i]) == "--scroll-area") {
            useScrollArea = true;
            for (int j = i; j + 1 < argc; ++j)
                argv[j] = argv[j + 1];
            --argc;
            break;
        }
    }

    QElapsedTimer clock;
    clock.start();
    const qint64 appStart = clock.nsecsElapsed();
    QApplication app(argc, argv);
    const qint64 appEnd = clock.nsecsElapsed();

    std::vector<qint64> ticks;
    QTimer heartbeat;
    heartbeat.setTimerType(Qt::PreciseTimer);
    QObject::connect(&heartbeat, &QTimer::timeout, [&] { ticks.push_back(clock.nsecsElapsed()); });
    heartbeat.start(10);

    const qint64 widgetStart = clock.nsecsElapsed();
    std::unique_ptr<QWidget> window;
    if (useScrollArea)
        window = std::make_unique<QAbstractScrollArea>();
    else
        window = std::make_unique<QWidget>();
    window->resize(1000, 600);
    const qint64 widgetEnd = clock.nsecsElapsed();

    drainEvents(50);
    const qint64 showStart = clock.nsecsElapsed();
    window->show();
    const qint64 showEnd = clock.nsecsElapsed();
    drainEvents(100);
    const qint64 drainEnd = clock.nsecsElapsed();

    qint64 crossShowGap = 0;
    for (size_t i = 1; i < ticks.size(); ++i) {
        if (ticks[i - 1] <= showStart && ticks[i] >= showEnd) {
            crossShowGap = ticks[i] - ticks[i - 1];
            break;
        }
    }

    QJsonArray rawTicks;
    for (const auto tick : ticks)
        rawTicks.append(QString::number(tick));
    const QJsonObject result{
        {"qt_version", qVersion()},
        {"platform", QGuiApplication::platformName()},
        {"mode", useScrollArea ? "scroll_area" : "widget"},
        {"widget_class", window->metaObject()->className()},
        {"window_size", "1000x600"},
        {"heartbeat_interval_ms", 10},
        {"qapplication_construct_ns", QString::number(appEnd - appStart)},
        {"qwidget_construct_resize_ns", QString::number(widgetEnd - widgetStart)},
        {"pre_show_event_drain_ms", 50},
        {"show_sync_ns", QString::number(showEnd - showStart)},
        {"post_show_event_drain_ms", 100},
        {"max_heartbeat_gap_ns", QString::number(maxGap(ticks))},
        {"cross_show_heartbeat_gap_ns", QString::number(crossShowGap)},
        {"drain_finished_ns", QString::number(drainEnd)},
        {"heartbeat_ticks_monotonic_ns", rawTicks},
        {"scope", "empty Qt widget show timing only; process-local diagnostic, no product data or logging"}};
    const auto bytes = QJsonDocument(result).toJson(QJsonDocument::Compact);
    fwrite(bytes.constData(), 1, static_cast<size_t>(bytes.size()), stdout);
    fputc('\n', stdout);
    return 0;
}
